import { test, expect } from '@playwright/test';

test.describe('/organizations — «publish tender» CTAs by role', () => {
  test('Guest: CTAs lead to registration', async ({ page }) => {
    // 1. Open /organizations without a session
    await page.goto('/organizations');
    const ctas = page.locator('a[href="/publish/tender"]');
    await expect(ctas.first()).toBeVisible();
    const count = await ctas.count();
    expect(count).toBeGreaterThanOrEqual(3);

    // 2. Click every tender-publish CTA (back between clicks)
    for (let i = 0; i < count; i++) {
      await page.goto('/organizations');
      await ctas.nth(i).scrollIntoViewIfNeeded();
      await ctas.nth(i).click();
      await expect(page).toHaveURL(/\/register/);
    }
  });
});
